-- INSERT INTO public.biblioteca_vectores (id, coleccion, materia, contenido, num_articulo, fuente, metadata, embedding, jurisdiccion, fuente_tipo, es_norma_vigente)
-- VALUES
--   ('mayalex_normativos:decreto_284_2013_titulo_ii_a15', 'mayalex_normativos', '10_LEYES_REGLAMENTOS', 'ARTÍCULO 15.- Es lícito el pacto en el que las partes acuerden renunciar al procedimiento judicial para la ejecución de garantías y sujetarse a un procedimiento especial de ejecución ante notario. El pacto suscrito para tal efecto puede constar en el mismo instrumento público que contenga la garantía o en instrumento público separado y debe ser inscrito en el registro de la propiedad que corresponda. Dicho pacto debe establecer el precio base del inmueble dado en garantía y la forma del requerimiento, y sujetarse a los procedimientos establecidos en este decreto.', '15', 'Decreto 284-2013 (La Gaceta 33,445), Título II', '{"norm_id":"mayalex_normativos:decreto_284_2013_titulo_ii","instrumento":"Decreto 284-2013, Título II (arts. 15 a 25)","rol":"PRIMARY","hash_texto_sha256":"2041de91688dc109999bfc39e4f91d910555c7ca12eb26cf9defc72d8def3ebd","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[],"vigencia_metadata":"TRUE_PRESUNTA (solo metadata)","gaceta":"La Gaceta 33,445 (5-jun-2014)"}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'ley', false),
--   ('mayalex_normativos:decreto_284_2013_titulo_ii_a16', 'mayalex_normativos', '10_LEYES_REGLAMENTOS', 'ARTÍCULO 16.- El Notario encargado de la ejecución deberá verificar que la obligación conste en instrumento público válido y que sea actualmente exigible. Hecho ésto, debe requerir al deudor para que cumpla con la obligación contraída en el término de veinticuatro (24) horas. En el mismo acto del requerimiento debe notificársele:
--    1) La obligación pendiente y el monto de la misma;
--    2) El nombre del titular, el lugar donde pueda pagarse o el nombre del establecimiento bancario y número de cuenta bancaria en la que puede consignar el valor;
--    3) El día, lugar y hora en la que se llevará a cabo la venta en pública subasta del bien dado en garantía conforme al precio base establecido en el contrato; y ,
--    4) La expresión de ante quien debe efectuarse el pago o consignación, que puede hacerse antes del plazo señalado para el evento.
--    Ante este requerimiento no podrá hacerse más oposición que el pago.', '16', 'Decreto 284-2013 (La Gaceta 33,445), Título II', '{"norm_id":"mayalex_normativos:decreto_284_2013_titulo_ii","instrumento":"Decreto 284-2013, Título II (arts. 15 a 25)","rol":"PRIMARY","hash_texto_sha256":"412eb8af33e443f30b5d8af754579ba599cffd402b7ceb14a6d9e7a8ea284684","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[],"vigencia_metadata":"TRUE_PRESUNTA (solo metadata)","gaceta":"La Gaceta 33,445 (5-jun-2014)"}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'ley', false),
--   ('mayalex_normativos:decreto_284_2013_titulo_ii_a17', 'mayalex_normativos', '10_LEYES_REGLAMENTOS', 'ARTÍCULO 17.- El requerimiento puede hacerse en una dirección física o electrónica previamente pactada, o en su defecto en el domicilio o el lugar de empleo del deudor. Si el mismo no se encontrare presente bastará con fijar una copia en la entrada del lugar debiendo también entregársele copia a cualquier persona que allí se encuentre y a dos (2) de los vecinos del lugar quienes actuarán como testigos del acto. Además, puede realizarse una filmación en vídeo de estas actuaciones la cual tendrá fuerza legal. Si se desconociere el paradero del deudor, el requerimiento debe publicarse durante tres (3) veces consecutivas con un (1) día de separación, en un diario de los de mayor circulación y un medio de comunicación masiva con cobertura en el lugar del último domicilio conocido de éste, después de lo cual se puede proceder con la ejecución.', '17', 'Decreto 284-2013 (La Gaceta 33,445), Título II', '{"norm_id":"mayalex_normativos:decreto_284_2013_titulo_ii","instrumento":"Decreto 284-2013, Título II (arts. 15 a 25)","rol":"PRIMARY","hash_texto_sha256":"fcd598af5bcd04a3c90383157386ce87353c0e4ab1fa0ff3ab7b9ff5bd1c006d","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[],"vigencia_metadata":"TRUE_PRESUNTA (solo metadata)","gaceta":"La Gaceta 33,445 (5-jun-2014)"}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'ley', false),
--   ('mayalex_normativos:decreto_284_2013_titulo_ii_a18', 'mayalex_normativos', '10_LEYES_REGLAMENTOS', 'ARTÍCULO 18.- Cuando el pago se hiciere efectivo ante el Notario en el plazo señalado, éste debe acreditar el mismo y dar por cerrado el expediente, extendiendo el correspondiente recibo, si se acreditase que el pago había sido hecho con anterioridad al requerimiento el notario debe suspender el proceso y remitir las diligencias ante el Juez de Letras correspondientes a fin de que el mismo pueda determinar la veracidad o no del pago, para lo cual debe dentro de las veinticuatro (24) horas siguientes a la recepción
--    de las diligencias abrirse de oficio la causa a prueba por un plazo no mayor de cinco (5) días hábiles comunes después de las cuales debe ordenar el cierre de dicho período de oficio. Si se determinare que el pago es suficiente para dar cumplida la obligación, el juez debe emitir resolución ordenando la suspensión definitiva del proceso y el cierre de las diligencias.
--    Si resultare que el pago no ha sido efectivo o que el mismo es insuficiente. Para dar por cumplida la obligación el juez de Letras debe emitir la resolución respectiva dentro del mismo plazo establecido en el párrafo anterior, mandando que las diligencias sean enviadas nuevamente al notario para que este concluya el proceso de ejecución si hubiere habido un pago parcial de ejecución debe llevarse a cabo por el remanente.
--    La resolución del juez debe ser emitido en un plazo no mayor de cuarenta y ocho (48) horas después de cerrado el período probatorio establecido en el párrafo primero de este Artículo.', '18', 'Decreto 284-2013 (La Gaceta 33,445), Título II', '{"norm_id":"mayalex_normativos:decreto_284_2013_titulo_ii","instrumento":"Decreto 284-2013, Título II (arts. 15 a 25)","rol":"PRIMARY","hash_texto_sha256":"7d9a9210bdd05fffcbe95227ba8090367a0d0a4bfbd2c1ed42d6d988afe68e6d","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[],"vigencia_metadata":"TRUE_PRESUNTA (solo metadata)","gaceta":"La Gaceta 33,445 (5-jun-2014)"}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'ley', false),
--   ('mayalex_normativos:decreto_284_2013_titulo_ii_a19', 'mayalex_normativos', '10_LEYES_REGLAMENTOS', 'ARTÍCULO 19.- El acta donde conste el requerimiento o notificación por Notario debe inscribirse en el mismo asiento en el que se haya inscrito la garantía. El registro de la notificación o requerimiento como anotación en el asiento donde se encuentre inscrito el bien o el acto o contrato tiene el mismo valor de los embargos decretados judicialmente.', '19', 'Decreto 284-2013 (La Gaceta 33,445), Título II', '{"norm_id":"mayalex_normativos:decreto_284_2013_titulo_ii","instrumento":"Decreto 284-2013, Título II (arts. 15 a 25)","rol":"PRIMARY","hash_texto_sha256":"bbeb235d1d253eca9e8c05e2987dd911c4280666a74fbdd8b3df1091fe7625ec","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[],"vigencia_metadata":"TRUE_PRESUNTA (solo metadata)","gaceta":"La Gaceta 33,445 (5-jun-2014)"}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'ley', false),
--   ('mayalex_normativos:decreto_284_2013_titulo_ii_a20', 'mayalex_normativos', '10_LEYES_REGLAMENTOS', 'ARTÍCULO 20.- La venta debe hacerse en pública subasta a favor de quien ofrezca el mejor precio.
--    El acreedor puede participar en la subasta ofertando el valor de su crédito o un monto superior.
--    En caso de que nadie participe en la subasta se debe adjudicar el bien a favor del acreedor sin necesidad de que éste oferte su
--    crédito. En los casos en que el valor del bien rematado no cubra el pago total de la obligación queda a salvo el derecho del acreedor de perseguir otros bienes del deudor, debiendo constar en el acta correspondiente.
--    De todo lo actuado debe levantarse el acta correspondiente. Esta acta servirá de título traslaticio del dominio sobre la garantía, debiendo inscribirse la misma.', '20', 'Decreto 284-2013 (La Gaceta 33,445), Título II', '{"norm_id":"mayalex_normativos:decreto_284_2013_titulo_ii","instrumento":"Decreto 284-2013, Título II (arts. 15 a 25)","rol":"PRIMARY","hash_texto_sha256":"428d7f5fb97ff7d63c0ab2cd3fb3d3ae8a328c2efef32bb95cf13d1834d600f7","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[],"vigencia_metadata":"TRUE_PRESUNTA (solo metadata)","gaceta":"La Gaceta 33,445 (5-jun-2014)"}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'ley', false),
--   ('mayalex_normativos:decreto_284_2013_titulo_ii_a21', 'mayalex_normativos', '10_LEYES_REGLAMENTOS', 'ARTÍCULO 21.- Las normas para determinar la prioridad y prelación de derechos de los acreedores sobre las garantías son determinadas por la legislación de derecho privado que corresponda.', '21', 'Decreto 284-2013 (La Gaceta 33,445), Título II', '{"norm_id":"mayalex_normativos:decreto_284_2013_titulo_ii","instrumento":"Decreto 284-2013, Título II (arts. 15 a 25)","rol":"PRIMARY","hash_texto_sha256":"de9f606674568b675477df7d5160441e92b0c1fe8d95ebb2046223b47f3e589b","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[],"vigencia_metadata":"TRUE_PRESUNTA (solo metadata)","gaceta":"La Gaceta 33,445 (5-jun-2014)"}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'ley', false),
--   ('mayalex_normativos:decreto_284_2013_titulo_ii_a22', 'mayalex_normativos', '10_LEYES_REGLAMENTOS', 'ARTÍCULO 22.- Cuando hayan otros acreedores garantizados por los bienes que se ejecutarán, el acreedor interesado en su ejecución debe notificarles a los otros acreedores a través de notario. Cuando estos otros acreedores hayan autorizado el empleo de una dirección física para practicar requerimientos y notificaciones, se les puede notificar en esa dirección.
--    Si no se encontraren en la misma, debe fijarse una copia de la notificación en la entrada del lugar, debiendo también entregársele copia a cualquier persona que ahí se encuentre y a dos (2) de los vecinos del lugar quienes deben servir de testigos de este acto.
--    Esta notificación debe inscribirse en el asiento en que se encuentre inscrito el bien dado en garantía.', '22', 'Decreto 284-2013 (La Gaceta 33,445), Título II', '{"norm_id":"mayalex_normativos:decreto_284_2013_titulo_ii","instrumento":"Decreto 284-2013, Título II (arts. 15 a 25)","rol":"PRIMARY","hash_texto_sha256":"6f6a12b5a5c70d9eb63243491f1a8e89a30d2cf9f89be30ffe25efd20a5ca0f7","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[],"vigencia_metadata":"TRUE_PRESUNTA (solo metadata)","gaceta":"La Gaceta 33,445 (5-jun-2014)"}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'ley', false),
--   ('mayalex_normativos:decreto_284_2013_titulo_ii_a23', 'mayalex_normativos', '10_LEYES_REGLAMENTOS', 'ARTÍCULO 23.- Cuando hayan varios acreedores éstos pueden ponerse de acuerdo ante un notario sobre la forma en que distribuirán los resultados de la venta por acreedor o de la venta extrajudicial por Notario.', '23', 'Decreto 284-2013 (La Gaceta 33,445), Título II', '{"norm_id":"mayalex_normativos:decreto_284_2013_titulo_ii","instrumento":"Decreto 284-2013, Título II (arts. 15 a 25)","rol":"PRIMARY","hash_texto_sha256":"880bd7f22009852d20cbced37637e8e0ae7fa65b715f063e90d4c20c102fd3f9","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[],"vigencia_metadata":"TRUE_PRESUNTA (solo metadata)","gaceta":"La Gaceta 33,445 (5-jun-2014)"}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'ley', false),
--   ('mayalex_normativos:decreto_284_2013_titulo_ii_a24', 'mayalex_normativos', '10_LEYES_REGLAMENTOS', 'ARTÍCULO 24.- Cuando no se pueda notificar a los otros acreedores que tengan derechos sobre la misma garantía o éstos no lleguen a un acuerdo después de ser notificados, debe solicitarse autorización especial del juez del domicilio donde se encuentren los bienes para seguir adelante con el proceso de ejecución.
--    Para el otorgamiento de esta autorización el juez puede solicitar que se rinda caución para garantizar los derechos de los otros acreedores. Esta notificación debe inscribirse en el registro público.
--    Contra esta resolución no cabe recurso alguno.', '24', 'Decreto 284-2013 (La Gaceta 33,445), Título II', '{"norm_id":"mayalex_normativos:decreto_284_2013_titulo_ii","instrumento":"Decreto 284-2013, Título II (arts. 15 a 25)","rol":"PRIMARY","hash_texto_sha256":"2a950e4d9dd72f15fc12633b4e87b9793ebae0cd447bda90494f7fac15825dcd","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[],"vigencia_metadata":"TRUE_PRESUNTA (solo metadata)","gaceta":"La Gaceta 33,445 (5-jun-2014)"}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'ley', false),
--   ('mayalex_normativos:decreto_284_2013_titulo_ii_a25', 'mayalex_normativos', '10_LEYES_REGLAMENTOS', 'ARTÍCULO 25.- El Notario ante quien se hubiese constituido una garantía no puede participar en la ejecución de la misma.', '25', 'Decreto 284-2013 (La Gaceta 33,445), Título II', '{"norm_id":"mayalex_normativos:decreto_284_2013_titulo_ii","instrumento":"Decreto 284-2013, Título II (arts. 15 a 25)","rol":"PRIMARY","hash_texto_sha256":"931e6372a1f82401cacc079213fe8d7cbc5ccef8ab0e08387eb7785518cb7de0","vigencia_state":"NO_VERIFICADO","verificado":false,"warnings":[],"vigencia_metadata":"TRUE_PRESUNTA (solo metadata)","gaceta":"La Gaceta 33,445 (5-jun-2014)"}'::jsonb, NULL /* EMBEDDINGS_PENDING */, 'HN', 'ley', false)
